%[text] # summarizeTestResult demo 1
%[text] This script shows how the `summarizeTestResult` function works. The function needs a proper test result XML file, which the Build Tool can generate.
%[text] Find an existing test result file.
test_result_file = SearchUtil1.searchFiles("sample-test-result.xml");
disp(test_result_file) %[output:364a0024]
assert(not(isempty(test_result_file)))
test_result_file = test_result_file(1);
%[text] Run the function.
test_summary = TestUtil1.summarizeTestResult(test_result_file);
%[text] The summary table has custom properties.
num_tests = test_summary.Properties.CustomProperties.NumTests;
disp("Number of tests: " + num_tests) %[output:86840f48]
disp("Total test time (seconds): " + test_summary.Properties.CustomProperties.TotalTestTime) %[output:2163678a]
median_test_time = test_summary.Properties.CustomProperties.MedianTestTime;
disp("Median test time (seconds): " + median_test_time) %[output:1b98668c]
%[text] The table has the rows of test results sorted by test time.
disp(head(test_summary)) %[output:818ad5a4]
threshold = 10;
assert(threshold < num_tests)

test_fullname = test_summary.TestClass + " > " + test_summary.TestFunction;
testname = test_fullname(1:threshold);
testname = flip(testname);

testtime = test_summary.TestTime;
testtime = flip(testtime(1:threshold));

fig = figure; %[output:1f3d433a]
fig.Position(3) = 900;  % width %[output:1f3d433a]
fig.Position(4) = 400;  % height %[output:1f3d433a]
ax = axes(fig); %[output:1f3d433a]

b = barh(ax, testname, testtime); %[output:1f3d433a]
b.Labels = b.YData;  % Show bar labels %[output:1f3d433a]

ax.TickLabelInterpreter = "none"; %[output:1f3d433a]
ax.FontName = "FixedWidth"; %[output:1f3d433a]
ax.Box = "off"; %[output:1f3d433a]
% axis(ax, "off")

xticks(ax, []) %[output:1f3d433a]

title(ax, ["Test time worst " + threshold; "Median test time " + median_test_time + " seconds"]) %[output:1f3d433a]
